import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] firstLine = br.readLine().split(" ");
        int n = Integer.parseInt(firstLine[0]);
        int m = Integer.parseInt(firstLine[1]);
        String[] aLine = br.readLine().split(" ");
        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = Integer.parseInt(aLine[i]) % m;
        }

        Set<Integer> firstHalf = new HashSet<>();
        Set<Integer> secondHalf = new HashSet<>();

        generateAllSums(firstHalf, a, 0, n / 2, 0, m);
        generateAllSums(secondHalf, a, n / 2, n, 0, m);

        List<Integer> secondHalfList = new ArrayList<>(secondHalf);
        Collections.sort(secondHalfList);

        int best = 0;
        for (int val : firstHalf) {
            int pos = Collections.binarySearch(secondHalfList, m - val);
            if (pos < 0) {
                pos = -pos - 1;
            }
            if (pos > 0) {
                int candidate = val + secondHalfList.get(pos - 1);
                if (candidate > best) {
                    best = candidate;
                }
            }
        }
        System.out.println(best);
    }

    private static void generateAllSums(Set<Integer> sumsSet, int[] a, int start, int end, int current, int m) {
        if (start == end) {
            sumsSet.add(current);
        } else {
            generateAllSums(sumsSet, a, start + 1, end, (current + a[start]) % m, m);
            generateAllSums(sumsSet, a, start + 1, end, current, m);
        }
    }
}
